    'ac.hint': { en: "Drag to orbit the agent. It watches the markets so you don't have to.", es: 'Arrastra para orbitar al agente. Vigila los mercados para que tú no tengas que hacerlo.', zh: '拖曳以環繞代理。它替你盯著市場。', pt: 'Arraste para orbitar o agente. Ele vigia os mercados para que não tenha de o fazer.', fr: 'Faites glisser pour orbiter autour de l’agent. Il surveille les marchés à votre place.', de: 'Ziehen, um den Agenten zu umkreisen. Er beobachtet die Märkte, damit du es nicht musst.', nl: 'Sleep om om de agent te draaien. Hij houdt de markten in de gaten, zodat jij dat niet hoeft.', ja: 'ドラッグしてエージェントの周りを回せます。あなたの代わりに市場を見ています。', ko: '드래그해 에이전트 주위를 돌려보세요. 당신 대신 시장을 지켜봅니다.', ru: 'Перетащите, чтобы облететь агента. Он следит за рынками вместо вас.', tr: 'Ajanın çevresinde dönmek için sürükle. Piyasaları senin yerine o izliyor.', ar: 'اسحب للدوران حول الوكيل. إنه يراقب الأسواق نيابة عنك.' },
    'ac.title': { en: 'The <span>AI Viking</span> Agent', es: 'El agente <span>AI Viking</span>', zh: '<span>AI Viking</span> 代理', pt: 'O agente <span>AI Viking</span>', fr: 'L’agent <span>AI Viking</span>', de: 'Der <span>AI Viking</span>-Agent', nl: 'De <span>AI Viking</span>-agent', ja: '<span>AI Viking</span> エージェント', ko: '<span>AI Viking</span> 에이전트', ru: 'Агент <span>AI Viking</span>', tr: '<span>AI Viking</span> Ajanı', ar: 'وكيل <span>AI Viking</span>' },
    'ac.creed': { en: '<span>I ANALYZE.</span><span>I ADAPT.</span><span>I EXECUTE.</span><span>I WIN.</span>', es: '<span>ANALIZO.</span><span>ME ADAPTO.</span><span>EJECUTO.</span><span>GANO.</span>', zh: '<span>我分析。</span><span>我適應。</span><span>我執行。</span><span>我致勝。</span>', pt: '<span>ANALISO.</span><span>ADAPTO-ME.</span><span>EXECUTO.</span><span>VENÇO.</span>', fr: '<span>J’ANALYSE.</span><span>JE M’ADAPTE.</span><span>J’EXÉCUTE.</span><span>JE GAGNE.</span>', de: '<span>ICH ANALYSIERE.</span><span>ICH PASSE MICH AN.</span><span>ICH FÜHRE AUS.</span><span>ICH GEWINNE.</span>', nl: '<span>IK ANALYSEER.</span><span>IK PAS ME AAN.</span><span>IK VOER UIT.</span><span>IK WIN.</span>', ja: '<span>分析する。</span><span>適応する。</span><span>執行する。</span><span>勝つ。</span>', ko: '<span>나는 분석한다.</span><span>나는 적응한다.</span><span>나는 실행한다.</span><span>나는 이긴다.</span>', ru: '<span>Я АНАЛИЗИРУЮ.</span><span>Я АДАПТИРУЮСЬ.</span><span>Я ИСПОЛНЯЮ.</span><span>Я ПОБЕЖДАЮ.</span>', tr: '<span>ANALİZ EDERİM.</span><span>UYUM SAĞLARIM.</span><span>UYGULARIM.</span><span>KAZANIRIM.</span>', ar: '<span>أُحلّل.</span><span>أتكيّف.</span><span>أُنفّذ.</span><span>أفوز.</span>' },
    'ac.summoning': { en: 'Summoning the agent…<br><span class="muted small">(the 3D model appears once <code>/mascot/agent.glb</code> is added)</span>', es: 'Invocando al agente…<br><span class="muted small">(el modelo 3D aparece cuando se añade <code>/mascot/agent.glb</code>)</span>', zh: '正在召喚代理…<br><span class="muted small">（加入 <code>/mascot/agent.glb</code> 後即顯示 3D 模型）</span>', pt: 'A invocar o agente…<br><span class="muted small">(o modelo 3D aparece assim que <code>/mascot/agent.glb</code> for adicionado)</span>', fr: 'Invocation de l’agent…<br><span class="muted small">(le modèle 3D apparaît une fois <code>/mascot/agent.glb</code> ajouté)</span>', de: 'Agent wird beschworen…<br><span class="muted small">(das 3D-Modell erscheint, sobald <code>/mascot/agent.glb</code> hinzugefügt ist)</span>', nl: 'De agent wordt opgeroepen…<br><span class="muted small">(het 3D-model verschijnt zodra <code>/mascot/agent.glb</code> is toegevoegd)</span>', ja: 'エージェントを召喚中…<br><span class="muted small">（<code>/mascot/agent.glb</code> を追加すると3Dモデルが表示されます）</span>', ko: '에이전트를 소환하는 중…<br><span class="muted small">(<code>/mascot/agent.glb</code>를 추가하면 3D 모델이 나타납니다)</span>', ru: 'Вызываем агента…<br><span class="muted small">(3D-модель появится после добавления <code>/mascot/agent.glb</code>)</span>', tr: 'Ajan çağrılıyor…<br><span class="muted small">(<code>/mascot/agent.glb</code> eklendiğinde 3B model görünür)</span>', ar: 'جارٍ استدعاء الوكيل…<br><span class="muted small">(يظهر النموذج ثلاثي الأبعاد بعد إضافة <code>/mascot/agent.glb</code>)</span>' },
