    'dp.arb': { en: 'Funding-arb paper tracker', es: 'Rastreador (papel) de arbitraje de funding', zh: '資金費率套利模擬追蹤', pt: 'Rastreador (papel) de arbitragem de funding', fr: 'Suivi (papier) d’arbitrage de funding', ar: 'متتبع تحكيم التمويل (ورقي)', de: 'Funding-Arb-Papiertracker', nl: 'Funding-arb papiertracker', ja: '資金調達裁定のペーパートラッカー', ko: '펀딩 차익 모의 트래커', ru: 'Бумажный трекер фандинг-арбитража', tr: 'Fonlama arbitrajı kâğıt takipçisi' },
    'dp.dex': { en: 'DEX ↔ CEX — Hyperliquid vs this venue', es: 'DEX ↔ CEX — Hyperliquid vs este venue', zh: 'DEX ↔ CEX — Hyperliquid 對比本所', pt: 'DEX ↔ CEX — Hyperliquid vs este venue', fr: 'DEX ↔ CEX — Hyperliquid vs cette plateforme', ar: 'DEX ↔ CEX — Hyperliquid مقابل هذه المنصة', de: 'DEX ↔ CEX — Hyperliquid vs. diese Börse', nl: 'DEX ↔ CEX — Hyperliquid vs. deze beurs', ja: 'DEX ↔ CEX — Hyperliquid と当取引所', ko: 'DEX ↔ CEX — Hyperliquid 대 이 거래소', ru: 'DEX ↔ CEX — Hyperliquid против этой площадки', tr: 'DEX ↔ CEX — Hyperliquid bu borsaya karşı' },
