    'auth.tfa_hint': { en: 'From your authenticator app — or one of your saved backup codes.', es: 'Desde tu app de autenticación — o uno de tus códigos de respaldo guardados.', zh: '來自你的驗證器應用程式 — 或你儲存的其中一組備用碼。', pt: 'Da sua app de autenticação — ou um dos códigos de recuperação que guardou.', fr: 'Depuis votre application d’authentification — ou l’un de vos codes de secours enregistrés.', de: 'Aus deiner Authenticator-App — oder einer deiner gespeicherten Backup-Codes.', nl: 'Uit je authenticator-app — of een van je opgeslagen back-upcodes.', ja: '認証アプリ、または保存したバックアップコードのいずれかを入力してください。', ko: '인증 앱에서 — 또는 저장해 둔 백업 코드 중 하나를 입력하세요.', ru: 'Из приложения-аутентификатора — или один из сохранённых резервных кодов.', tr: 'Kimlik doğrulama uygulamanızdan — ya da kayıtlı yedek kodlarınızdan biri.', ar: 'من تطبيق المصادقة — أو أحد رموزك الاحتياطية المحفوظة.' },
    'auth.forgot': { en: 'Forgot your password?', es: '¿Olvidaste tu contraseña?', zh: '忘記密碼？', pt: 'Esqueceu-se da palavra-passe?', fr: 'Mot de passe oublié ?', de: 'Passwort vergessen?', nl: 'Wachtwoord vergeten?', ja: 'パスワードをお忘れですか？', ko: '비밀번호를 잊으셨나요?', ru: 'Забыли пароль?', tr: 'Parolanızı mı unuttunuz?', ar: 'هل نسيت كلمة المرور؟' },
    'auth.forgot_body': { en: 'Enter your email and we’ll send a link to reset your password.', es: 'Introduce tu correo y te enviaremos un enlace para restablecer la contraseña.', zh: '輸入你的電子郵件，我們會寄送重設密碼的連結。', pt: 'Introduza o seu email e enviaremos um link para redefinir a palavra-passe.', fr: 'Saisissez votre e-mail et nous vous enverrons un lien de réinitialisation.', de: 'Gib deine E-Mail ein und wir senden dir einen Link zum Zurücksetzen.', nl: 'Vul je e-mailadres in en we sturen een link om je wachtwoord te herstellen.', ja: 'メールアドレスを入力してください。パスワード再設定用のリンクをお送りします。', ko: '이메일을 입력하시면 비밀번호 재설정 링크를 보내드립니다.', ru: 'Введите почту — мы пришлём ссылку для сброса пароля.', tr: 'E-postanızı girin, parola sıfırlama bağlantısı gönderelim.', ar: 'أدخل بريدك الإلكتروني وسنرسل رابطًا لإعادة تعيين كلمة المرور.' },
